@cute.kernel
def with_bounds_check(data: cute.Tensor):
    tid = cute.arch.thread_idx()[0]
    bid = cute.arch.block_idx()[0]
    idx = bid * 256 + tid
    if idx < cute.size(data):
        data[idx] = 0.0

